def btn(text='Discuss your home',url='/contact.html',light=False):return f'<a class="btn{" light" if light else ""}" href="{url}">{text} <span aria-hidden="true">↗</span></a>'
def cards(limit=None):
 return '<div class="service-grid">'+''.join(f'<article class="service-card reveal {"featured" if i==0 else ""}"><span class="number">{n}</span><h3>{t}</h3><p>{d}</p><a class="text-link" href="/{u}">Explore service <span aria-hidden="true">↗</span></a></article>' for i,(u,n,t,d) in enumerate(services[:limit]))+'</div>'
