  out+=f'<article class="project reveal" data-category="{cat}"><a class="project-photo" href="/assets/projects/{img}.webp" target="_blank" rel="noopener" aria-label="View full photograph: {title}"><img src="/assets/projects/{img}.webp" alt="{title} project photograph, {loc}" loading="lazy" width="960" height="720"><span class="photo-open">View photograph ↗</span></a><span class="project-category">{scope}</span><h3>{title}</h3><p>{desc if detail else loc}</p><div class="project-meta"><span>{loc}</span><span>Leaf Infra portfolio</span></div></article>'
