 document=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{titles[file]} | Leaf Infra</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta name="theme-color" content="#163c31"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{html.escape(titles[file])} | Leaf Infra"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://leafinfra.com/assets/projects/south-east-omr.webp"><link rel="icon" href="https://leafinfra.com/wp-content/uploads/2026/03/Leaf-Infra-1.png"><link rel="stylesheet" href="/assets/design.css"><script src="/assets/site.js" defer></script><script src="/assets/motion.js" defer></script><script type="application/ld+json">{json.dumps(schema,separators=(',',':'))}</script></head><body><a class="skip-link" href="#main">Skip to content</a><header><div class="wrap nav"><a class="brand" href="/" aria-label="Leaf Infra home"><img src="https://leafinfra.com/wp-content/uploads/2026/03/Leaf-Infra-1.png" alt="Leaf Infra" width="137" height="44"><small>Civil construction<br>Chennai · Tamil Nadu</small></a><nav class="navlinks" id="navlinks" aria-label="Main navigation">{links}</nav>{btn('Build with us')}<button class="menu-toggle" id="menuToggle" aria-label="Open navigation" aria-controls="navlinks" aria-expanded="false">☰</button></div></header><main id="main"><noscript><p class="wrap">Online enquiry forms require JavaScript. Call <a href="tel:+919345523646">+91 93455 23646</a> to discuss your project.</p></noscript>{content}</main>'''
